from pathlib import Path
import json
d=Path(__file__).resolve().parent
p=d/'anatomy_plan.json';plan=json.loads(p.read_text(encoding='utf-8'))
plan['identity']='Golden legless segmented parasite. Broad head with large two-row ivory teeth and dark mouth, gold ochre spots, one faceted flat-topped gold gem on head; two successively smaller body rings with a matching gold gem and lateral round gold plates, ending in a short smooth golden tapered rump. No visible eyeballs, antennae, legs, wings or long tail.'
p.write_text(json.dumps(plan,ensure_ascii=False,indent=2)+chr(10),encoding='utf-8')
for direction in ['Up','Down']:
    rear=direction=='Up'
    view='REAR view, moving AWAY up the screen. Head is the far TOP section, behind the round body. Rear of head has NO teeth, mouth or eyes; only the gold shell and original flat-topped gem. Back and rump face the viewer. Do not expose the underside or mouth on this view.' if rear else 'FRONT view, moving TOWARD viewer down the screen. Face is broad and centered, two original rows of large pointed ivory teeth and black mouth gap. No eyes: the round lateral gold plates are shell nodules. Body recedes upward behind the head.'
    heads=['the matching plain rear of the broad gold head, one flat-topped geometric gold gem, no mouth' if rear else 'complete upper head AND lower jaw as ONE detached closed-mouth head, TWO rows of large ivory teeth separated by narrow dark mouth gap; one original gold gem on top', 'same rear head and alignment' if rear else 'same complete head with mouth slightly open for attack, both rows of teeth and broad gold lower jaw, same original gem', 'same rear head and alignment' if rear else 'same complete head with original death damage: a few broken teeth, original gold shell and gem, no invented eyes or cross marks']
    slots=heads+['ONE rounded large body ring ONLY, gold ochre spotted shell, ONE flat-topped gold gem on TOP center and lateral round gold plates, solid opaque connection surfaces. Axial view, not side profile. No head or teeth or other body rings.', 'ONE smaller middle/rear ring ONLY, gold ochre spotted shell, ONE smaller flat-topped gold gem on TOP center, solid opaque connection surfaces, axial view. No head or teeth or rear tip.', 'ONE short smooth round-tapered gold rear tip ONLY, no gem, no spines, no long tail, solid opaque connection end. Rear-view rounded rump, not a pointed cone aimed at viewer.']
    prompt='Use case: identity-preserve. Asset type: production 2D Unity cutout sprite parts sheet.'+chr(10)+'Image 1 is the current original atlas. Image 2 is the assembled original creature, reference only. Match exact golden palette, thick smooth dark outline, simple flat cel shading, spots, proportions and flat-topped gold gems. '+plan['identity']+chr(10)+view+chr(10)+'Exactly 4 equal columns by 2 equal rows, exactly 6 detached parts in reading order:'+chr(10)+chr(10).join(str(i+1)+'. '+s for i,s in enumerate(slots))+chr(10)+'Cells 7 and 8 empty. Each part fits its own cell with 12 percent margin. No assembled animal or additional pieces. Rings and head must overlap naturally without holes; no interior magenta. This is a LOW crawling larva, not upright humanoid or snake. No side-view fakery, no eyes, no legs, no antennae, no wings, no extra organs. Head expression alignment identical. Background exactly flat RGB #FF00FF magenta immediately outside all outlines. No ground or shadows, no halos, no checkerboard, no labels, no text or watermark. Crisp intact anti-aliased outlines.'
    (d/'generation'/direction/'prompt.txt').write_text(prompt,encoding='utf-8')
